-- AD-MAB-INC-01 (inclusion): 同意取得時の年齢が50歳以上85歳以下の者。
c_ad_mab_inc_01 AS (
  SELECT b.pid, b.index_date, (((year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) >= 50) AND ((year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) <= 85)) AS v,
         concat_ws(';', NULL) AS ev
  FROM base b
  ),
a_ad_mab_inc_02_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MILD_COGNITIVE_IMPAIRMENT_OR_ALZHEIMER_S_DISEASE' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
a_ad_mab_inc_02_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MILD_COGNITIVE_IMPAIRMENT_OR_ALZHEIMER_S_DISEASE' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MILD_COGNITIVE_IMPAIRMENT_OR_ALZHEIMER_S_DISEASE' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MILD_COGNITIVE_IMPAIRMENT_OR_ALZHEIMER_S_DISEASE' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ad_mab_inc_02_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MILD_COGNITIVE_IMPAIRMENT_OR_ALZHEIMER_S_DISEASE' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MILD_COGNITIVE_IMPAIRMENT_OR_ALZHEIMER_S_DISEASE' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= b.index_date
  GROUP BY b.pid, b.index_date),
-- AD-MAB-INC-02 (inclusion): アルツハイマー病による軽度認知障害（MCI）または軽度のアルツハイマー型認知症と診断されている者（ICD-10-CM G31.84 または G30）。
c_ad_mab_inc_02 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_ad_mab_inc_02_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_ad_mab_inc_02_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_ad_mab_inc_02_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_ad_mab_inc_02_1.ev, a_ad_mab_inc_02_1_off.ev, a_ad_mab_inc_02_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ad_mab_inc_02_1 ON a_ad_mab_inc_02_1.pid = b.pid AND a_ad_mab_inc_02_1.index_date = b.index_date
  LEFT JOIN a_ad_mab_inc_02_1_nd ON a_ad_mab_inc_02_1_nd.pid = b.pid AND a_ad_mab_inc_02_1_nd.index_date = b.index_date
  LEFT JOIN a_ad_mab_inc_02_1_off ON a_ad_mab_inc_02_1_off.pid = b.pid AND a_ad_mab_inc_02_1_off.index_date = b.index_date),
a_ad_mab_exc_01_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ad_mab_exc_01_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
