  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ANTICOAGULANT' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc))) OR (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ANTICOAGULANT' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ad_mab_exc_01_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ANTICOAGULANT' AND vsf.system = 'http://www.whocc.no/atc' AND starts_with(x.atc, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc)) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ANTICOAGULANT' AND vsf.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND starts_with(x.nhi_code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ANTICOAGULANT' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -90) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- AD-MAB-EXC-01 (exclusion): スクリーニング前90日以内に抗凝固薬（ワルファリン、直接経口抗凝固薬）を使用した者。
c_ad_mab_exc_01 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_ad_mab_exc_01_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_ad_mab_exc_01_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_ad_mab_exc_01_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_ad_mab_exc_01_1.ev, a_ad_mab_exc_01_1_off.ev, a_ad_mab_exc_01_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ad_mab_exc_01_1 ON a_ad_mab_exc_01_1.pid = b.pid AND a_ad_mab_exc_01_1.index_date = b.index_date
  LEFT JOIN a_ad_mab_exc_01_1_nd ON a_ad_mab_exc_01_1_nd.pid = b.pid AND a_ad_mab_exc_01_1_nd.index_date = b.index_date
  LEFT JOIN a_ad_mab_exc_01_1_off ON a_ad_mab_exc_01_1_off.pid = b.pid AND a_ad_mab_exc_01_1_off.index_date = b.index_date),
a_ad_mab_exc_03_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ad_mab_exc_03_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_STROKE' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ad_mab_exc_03_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_STROKE' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_STROKE' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ad_mab_exc_03_2 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TRANSIENT_ISCHEMIC_ATTACK' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ad_mab_exc_03_2_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TRANSIENT_ISCHEMIC_ATTACK' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
-- AD-MAB-EXC-03 (exclusion): スクリーニング前12か月以内に脳卒中または一過性脳虚血発作（TIA）の既往がある者。
c_ad_mab_exc_03 AS (
  SELECT b.pid, b.index_date, ((CASE WHEN (coalesce(a_ad_mab_exc_03_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_ad_mab_exc_03_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_ad_mab_exc_03_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) OR (CASE WHEN (coalesce(a_ad_mab_exc_03_2.n, 0) > 0) THEN TRUE WHEN (coalesce(a_ad_mab_exc_03_2_nd.n, 0) > 0) THEN NULL ELSE FALSE END)) AS v,
         concat_ws(';', coalesce(a_ad_mab_exc_03_1.ev, a_ad_mab_exc_03_1_off.ev, a_ad_mab_exc_03_1_nd.ev), coalesce(a_ad_mab_exc_03_2.ev, a_ad_mab_exc_03_2_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ad_mab_exc_03_1 ON a_ad_mab_exc_03_1.pid = b.pid AND a_ad_mab_exc_03_1.index_date = b.index_date
  LEFT JOIN a_ad_mab_exc_03_1_nd ON a_ad_mab_exc_03_1_nd.pid = b.pid AND a_ad_mab_exc_03_1_nd.index_date = b.index_date
  LEFT JOIN a_ad_mab_exc_03_1_off ON a_ad_mab_exc_03_1_off.pid = b.pid AND a_ad_mab_exc_03_1_off.index_date = b.index_date
  LEFT JOIN a_ad_mab_exc_03_2 ON a_ad_mab_exc_03_2.pid = b.pid AND a_ad_mab_exc_03_2.index_date = b.index_date
  LEFT JOIN a_ad_mab_exc_03_2_nd ON a_ad_mab_exc_03_2_nd.pid = b.pid AND a_ad_mab_exc_03_2_nd.index_date = b.index_date),
a_ad_mab_exc_04_1_creatinine AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END) > 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 1.0 WHEN 'umol/l' THEN o.value_num * 0.011312217194570135 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
    WHERE o.system = 'http://loinc.org' AND o.code = '2160-0') WHERE rn = 1),
a_ad_mab_exc_04_1_v AS (
  SELECT b.pid, b.index_date, (CASE WHEN creatinine.conv IS NULL OR creatinine.conv <= 0 OR (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) IS NULL OR (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) < 18 OR (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) IS NULL THEN NULL ELSE 194.0 * pow(creatinine.conv, -1.094) * pow((year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END), -0.287) * (CASE WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) THEN 0.739 ELSE 1.0 END) END) AS val, concat_ws(';', creatinine.oid || '|' || strftime(creatinine.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN creatinine.oid IS NULL OR creatinine.value_num IS NULL THEN 'derived_missing_input:creatinine' WHEN creatinine.conv IS NULL THEN 'derived_unit:creatinine' WHEN (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) IS NULL OR (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) <= 0 THEN 'derived_missing_input:age' WHEN (year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) < 18 THEN 'derived_adult_only:age' WHEN (CASE WHEN b.sex IN ('male', 'female') THEN b.sex = 'female' ELSE NULL END) IS NULL THEN 'derived_missing_input:sex' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_ad_mab_exc_04_1_creatinine creatinine ON creatinine.pid = b.pid AND creatinine.index_date = b.index_date),
a_ad_mab_exc_04_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_ad_mab_exc_04_1_v),
-- AD-MAB-EXC-04 (exclusion): eGFRが30 mL/min/1.73m²未満の者（日本腎臓学会の推算式による）。
c_ad_mab_exc_04 AS (
  SELECT b.pid, b.index_date, (a_ad_mab_exc_04_1.val < 30) AS v,
         concat_ws(';', a_ad_mab_exc_04_1.ev) AS ev
  FROM base b
  LEFT JOIN a_ad_mab_exc_04_1 ON a_ad_mab_exc_04_1.pid = b.pid AND a_ad_mab_exc_04_1.index_date = b.index_date)
SELECT b.pid, b.index_date,
  c_ad_mab_inc_01.v AS "C_AD-MAB-INC-01", c_ad_mab_inc_01.ev AS "E_AD-MAB-INC-01",
  c_ad_mab_inc_02.v AS "C_AD-MAB-INC-02", c_ad_mab_inc_02.ev AS "E_AD-MAB-INC-02",
  c_ad_mab_exc_01.v AS "C_AD-MAB-EXC-01", c_ad_mab_exc_01.ev AS "E_AD-MAB-EXC-01",
  c_ad_mab_exc_03.v AS "C_AD-MAB-EXC-03", c_ad_mab_exc_03.ev AS "E_AD-MAB-EXC-03",
  c_ad_mab_exc_04.v AS "C_AD-MAB-EXC-04", c_ad_mab_exc_04.ev AS "E_AD-MAB-EXC-04"
FROM base b
LEFT JOIN c_ad_mab_inc_01 ON c_ad_mab_inc_01.pid = b.pid AND c_ad_mab_inc_01.index_date = b.index_date
LEFT JOIN c_ad_mab_inc_02 ON c_ad_mab_inc_02.pid = b.pid AND c_ad_mab_inc_02.index_date = b.index_date
LEFT JOIN c_ad_mab_exc_01 ON c_ad_mab_exc_01.pid = b.pid AND c_ad_mab_exc_01.index_date = b.index_date
LEFT JOIN c_ad_mab_exc_03 ON c_ad_mab_exc_03.pid = b.pid AND c_ad_mab_exc_03.index_date = b.index_date
LEFT JOIN c_ad_mab_exc_04 ON c_ad_mab_exc_04.pid = b.pid AND c_ad_mab_exc_04.index_date = b.index_date
ORDER BY b.pid, b.index_date
